# EventLog endpoints
@app.post("/simulations/{simulation_run_id}/events/", response_model=schemas.EventLog, tags=["Events"])
def create_event_log(
    simulation_run_id: int, event_log: schemas.EventLogCreate, db: Session = Depends(get_db)
):
